% cached     : False
% title      : Automatically generated logs
:- pred high_risk_ai_system/1, gloss('AI system classified as high-risk'), source('celex:32024R1689/oj#art_19').
:- pred automatically_generated_logs/2, gloss('logs automatically generated by an AI system'), source('celex:32024R1689/oj#art_19').
:- pred under_control/2, gloss('an object is under the control of an actor'), source('celex:32024R1689/oj#art_19').
:- pred financial_institution_subject_to_union_financial_services_law/1, gloss('financial institution subject to internal governance requirements under Union financial services law'), source('celex:32024R1689/oj#art_19').
:- pred must_keep(2), gloss('actor must keep an object'), source('celex:32024R1689/oj#art_19').
:- pred must_maintain(2), gloss('actor must maintain an object'), source('celex:32024R1689/oj#art_19').

% Paragraph 1: Providers of high-risk AI systems shall keep automatically generated logs under their control.
must_keep(Provider, logs(Logs, System, period(months(6)))) :-
    provider(Provider),
    high_risk_ai_system(System),
    automatically_generated_logs(Logs, System),
    under_control(Logs, Provider).

% Paragraph 2: Providers that are financial institutions subject to internal governance requirements under Union financial services law shall maintain logs as part of documentation under relevant financial services law.
must_maintain(Provider, documentation(Logs, under_financial_services_law)) :-
    provider(Provider),
    financial_institution_subject_to_union_financial_services_law(Provider),
    high_risk_ai_system(System),
    automatically_generated_logs(Logs, System).

provenance(must_keep/2, 'celex:32024R1689/oj#art_19').
provenance(must_maintain/2, 'celex:32024R1689/oj#art_19').

references('celex:32024R1689/oj#art_19', 'celex:32024R1689/oj#art_12/par_1').
